import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    # Find connected components using Union-Find
    parent = list(range(n + 1))  # 1-indexed

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]  # Path compression
            u = parent[u]
        return u

    def union(u, v):
        pu, pv = find(u), find(v)
        if pu != pv:
            parent[pu] = pv

    for i in range(2, 2 + 2*m, 2):
        u = int(data[i])
        v = int(data[i+1])
        union(u, v)

    # Count component sizes
    component_sizes = {}
    for i in range(1, n+1):
        root = find(i)
        if root not in component_sizes:
            component_sizes[root] = 0
        component_sizes[root] += 1

    # Calculate total connections
    total_connections = 0
    for size in component_sizes.values():
        total_connections += (size - 1)

    # Maximum danger is 2^total_connections
    print(2 ** total_connections)

if __name__ == "__main__":
    solve()
"}

