import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        a = int(next(it))
        b = int(next(it))
        k = int(next(it))

        # Read boys for each pair
        boys = [int(next(it)) for _ in range(k)]

        # Read girls for each pair
        girls = [int(next(it)) for _ in range(k)]

        # Count occurrences of each boy and girl
        count_boys = {}
        count_girls = {}

        for boy in boys:
            count_boys[boy] = count_boys.get(boy, 0) + 1

        for girl in girls:
            count_girls[girl] = count_girls.get(girl, 0) + 1

        # Total ways to choose 2 pairs
        total = k * (k - 1) // 2

        # Subtract pairs sharing a boy
        for cnt in count_boys.values():
            total -= cnt * (cnt - 1) // 2

        # Subtract pairs sharing a girl
        for cnt in count_girls.values():
            total -= cnt * (cnt - 1) // 2

        print(total)

if __name__ == "__main__":
    solve()
"}

