import sys

def main():
    l, r = map(int, sys.stdin.read().split())

    # For each divisor d from 2 to r, count how many multiples of d are in [l, r]
    max_count = 0
    best_divisor = 2

    for d in range(2, r + 1):
        # Count multiples of d in [l, r]
        count = (r // d) - ((l - 1) // d)

        if count > max_count:
            max_count = count
            best_divisor = d
        elif count == max_count:
            # If there's a tie, we can choose any, so we just keep the first one
            pass

    print(best_divisor)

if __name__ == "__main__":
    main()
"}

