import sys

def main():
    l, r = map(int, sys.stdin.read().split())

    # For d = 2, count even numbers in [l, r]
    count_2 = (r // 2) - ((l - 1) // 2)

    # For d = l, count multiples of l in [l, r]
    count_l = (r // l) - ((l - 1) // l)

    if count_2 > count_l:
        print(2)
    elif count_2 < count_l:
        print(l)
    else:
        # If counts are equal, we can return any; prefer 2
        print(2)

