    if lengths[i] == 1:
        # We can have at most 2 words of length 1
        if len(words) == 0:
            words.append("0")
        elif len(words) == 1:
            words.append("1")
        else:
            # Already have 2 words of length 1, no more needed
            pass
    else:
        # For words of length > 1, we need to ensure no prefix conflicts
        # Start with "1" to avoid prefix conflicts with "0"
        prefix = "1"
        for j in range(len(words)):
            if words[j].startswith(prefix):
                # This word would be a prefix of an existing word
                print("NO")
                exit()
        # Add the new word
        words.append(prefix)
        # Add more characters to make it the required length
        for k in range(1, lengths[i]):
            words[-1] += "1"

# Check if we have enough words
if len(words) != n:
    print("NO")
else:
    print("YES")
    for word in words:
        print(word)
