{"code": "
def factorial(n):
    if n == 0:
        return 1
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

def combination(n, k):
    if k > n or k < 0:
        return 0
    return factorial(n) // (factorial(k) * factorial(n - k))

# Read input
n, m = map(int, input().split())
a = list(map(int, input().split()))

# Brute force over all distributions of students
# We need to count the number of ways to distribute n students among m rooms
# such that room i gets xi students

expected = 0.0
# This is m^n, the total number of distributions
total_distributions = m ** n

# We'll use a recursive approach to generate all distributions
# Or we can use multinomial coefficients

# Instead of generating all combinations, let's use dynamic programming

# DP state: dp[i][j] = number of ways to assign j students to first i rooms
# This is just combinations

dp = [{} for _ in range(m + 1)]
dp[0][0] = 1  # Base case: 0 students assigned to 0 rooms

for i in range(1, m + 1):
    for j in range(n + 1):
        # For each distribution of j students to first i-1 rooms
        for count in dp[i - 1].get(j, []):
            # Try assigning x students to room i
            for x in range(j + 1):
                ways = combination(j, x)
                # Queue size for this room
                queue_size = (x + a[i - 1] - 1) // a[i - 1]
                # Update dp[i]
                if (j - x) in dp[i]:
                    dp[i][j - x] += count * ways
                else:
                    dp[i][j - x] = count * ways

# Now compute the expected max queue size
# For each distribution of students, we need to know the max queue size

# Actually, let me reconsider. I should track the max queue size in the DP

# Let me use dp[i][j][k] where k is the max queue size

dp = [{} for _ in range(m + 1)]
dp[0][0] = 1  # Base case

for i in range(1, m + 1):
    current_room_capacity = a[i - 1]
    for total_students in range(n + 1):
        for current_max in list(dp[i - 1].keys()):
            count = dp[i - 1][current_max]
            for x in range(total_students + 1):
                ways = combination(total_students, x)
                queue_size = (x + current_room_capacity - 1) // current_room_capacity
                new_max = max(current_max, queue_size)
                if new_max in dp[i]:
                    dp[i][new_max] += count * ways
                else:
                    dp[i][new_max] = count * ways

expected = 0.0
for max_queue_size, count in dp[m].items():
    expected += max_queue_size * count

print(f"{expected / total_distributions:.20f}")
