    n = int(input())
    pairs = []
    for i in range(1, n + 1):
        a, b = map(int, input().split())
        pairs.append((a, b, i))

    # Sort pairs by their smaller element
    pairs.sort(key=lambda x: min(x[0], x[1]))

    # Try to construct the sequence greedily
    sequence = []
    for pair in pairs:
        if not sequence:
            # First pair, just add it
            sequence.append(pair)
        else:
            # Check if we can add this pair based on the current pattern
            last = sequence[-1]
            if len(sequence) % 2 == 1:
                # We expect an 'up' step: last element < current element
                if last[0] < pair[0] and last[0] < pair[1]:
                    sequence.append(pair)
            else:
                # We expect a 'down' step: last element > current element
                if last[0] > pair[0] and last[0] > pair[1]:
                    sequence.append(pair)

    # Output the result
    print(len(sequence))
    print(' '.join(map(str, [pair[2] for pair in sequence])))

