def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        triangles = []
        for _ in range(n - 2):
            a, b, c = map(int, input().split())
            triangles.append(set([a, b, c]))

        # We need to find a valid polygon order and cut order
        # Let's try a greedy approach: start with any vertex and build the polygon

        # Find a vertex that appears only once (this will be the first vertex)
        start_vertex = None
        for i in range(n):
            count = 0
            for t in triangles:
                if i + 1 in t:
                    count += 1
            if count == 1:
                start_vertex = i + 1
                break

        # Build the polygon from start_vertex
        polygon = [start_vertex]
        current = start_vertex

        for _ in range(n - 1):
            # Find the next vertex that forms a triangle with the current vertex
            next_vertex = None
            for t in triangles:
                if current in t and next_vertex not in t:
                    next_vertex = t - {current}
                    break
            polygon.append(next_vertex)
            current = next_vertex

        # Find the cut order
        cut_order = []
        for i in range(n - 2):
            # The cut order is the reverse of the order in which vertices are removed
            # Find which vertex is removed from each triangle
            removed_vertex = None
            for t in triangles:
                if t - {polygon[i + 1]} == {polygon[i], polygon[i + 2]}:
                    removed_vertex = polygon[i + 1]
                    break
