left = list(map(int, input().split()))
top = []
for _ in range(n):
    top.append(list(map(int, input().split())))

# Initialize heights based on top view
heights = [[0 for _ in range(m)] for _ in range(n)]
for i in range(n):
    for j in range(m):
        if top[i][j] == 1:
            heights[i][j] = 1

# We need to ensure both row and column maxima match
# First, identify which cells are needed for row or column constraints
# Then we'll update them

# Find all cells that need to be updated
cells_to_update = []
for i in range(n):
    current_row_max = max(heights[i])
    if current_row_max < left[i]:
        # Need to increase some cells in this row
        cells_to_update.extend([(i, j) for j in range(m) if top[i][j] == 1])

for j in range(m):
    current_col_max = 0
    for i in range(n):
        current_col_max = max(current_col_max, heights[i][j])
    if current_col_max < front[j]:
        # Need to increase some cells in this column
        cells_to_update.extend([(i, j) for i in range(n) if top[i][j] == 1])

# Set the values in these cells to the required maxima
for i, j in cells_to_update:
    # The maximum required is the minimum of left[i] and front[j]
    heights[i][j] = min(left[i], front[j])

# Output the result with proper formatting
for row in heights:
    for val in row:
        print(f"{val} ", end="")
    print()

