import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    l = int(next(it))
    k = int(next(it))

    p = [int(next(it)) for _ in range(n)]
    a = [int(next(it)) for _ in range(n)]

    # dp[i][w][h][c]: probability after i tours, having won w tours,
    # having h huge prizes that need to be carried, and having c carrying capacity
    max_capacity = k + sum(a)

    # Use a 4D array with dimensions:
    # - i: 0..n (number of tours done)
    # - w: 0..n (number of wins)
    # - h: 0..(n+k) (number of huge prizes)
    # - c: 0..(k+max_sum_ai) (carrying capacity)

    # We only need to track up to max_capacity, which is at most 40200
    # But we can optimize by only keeping current and next states

    # dp[w][h][c]: probability with w wins, h huge prizes, c capacity
    dp_current = [[[0.0] * (max_capacity + 1) for _ in range(n + 1)] for __ in range(n + 1)]
    dp_next = [[[0.0] * (max_capacity + 1) for _ in range(n + 1)] for __ in range(n + 1)]

    dp_current[0][0][0] = 1.0

    for i in range(n):
        for w in range(i + 1):
