import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    money = list(map(int, data[1:1+n]))

    # Bubble sort with swaps that change money
    # We want non-decreasing order from front to back
    # When we swap, the left element decreases by 1, the right element increases by 1

    while True:
        swapped = False
        for i in range(n - 1):
            if money[i] > money[i + 1]:
                # Swap positions: left moves right (decreases), right moves left (increases)
                money[i] -= 1
                money[i + 1] += 1
                swapped = True
        if not swapped:
            break

    # Check if the array is non-decreasing from front to back
    for i in range(n - 1):
        if money[i] > money[i + 1]:
            print(":(")
            return

    print(" ".join(map(str, money)))

if __name__ == "__main__":
    solve()
