def matrix_mult(a, b, mod):
    """Multiply two matrices under modulo."""
    n = len(a)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            if a[i][k] == 0:
                continue
            for j in range(n):
                result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % mod
    return result


def matrix_pow(mat, power, mod):
    """Raise a matrix to a power using binary exponentiation."""
    n = len(mat)
    result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]  # Identity matrix
    while power > 0:
        if power % 2 == 1:
            result = matrix_mult(result, mat, mod)
        mat = matrix_mult(mat, mat, mod)
        power //= 2
    return result


def solve(C, W, H, mod):
    """Solve the problem using matrix exponentiation."""
    if C == 0:
        return 1

    # dp[c] = (H+1) * (dp[c-1] + dp[c-2] + ... + dp[c-W])
    # This is a linear recurrence relation of order W
    # We can use matrix exponentiation

    # Construct the transformation matrix
    n = W + 1  # State includes dp[c], dp[c-1], ..., dp[c-W]

    # Identity matrix for the state transition
    mat = [[0] * n for _ in range(n)]
    for i in range(n):
        mat[i][i] = 1

    # Add the recurrence relation
    for i in range(1, n):
        # dp[c] = (H+1) * (dp[c-1] + dp[c-2] + ... + dp[c-W])
        # So we add (H+1) to each of the previous states
        mat[0][i] = (mat[0][i] + H + 1) % mod

    # Matrix power is (C) because we start from dp[0] and need C steps
    mat_pow = matrix_pow(mat, C, mod)

    # Initial state vector: [dp[0], dp[-1], ..., dp[-W]]
    # For dp[0], we need dp[0] = 1, and for negative indices, we can treat them as 0
    state = [1] + [0] * W

    # Multiply state with the matrix power
    result = [0] * n
    for i in range(n):
        if state[i] == 0:
            continue
        for j in range(n):
            result[j] = (result[j] + state[i] * mat_pow[i][j]) % mod

    return result[0]


def main():
    C, W, H = map(int, input().split())
    mod = 10**6 + 3
    print(solve(C, W, H, mod))

if __name__ == "__main__":
    main()
