    grid = [input().strip() for _ in range(n)]

    # Precompute cost: cost[i][color] = number of changes to make column i color 'color'
    # where color 0 = white (.), color 1 = black (#)
    cost = [[0] * 2 for _ in range(m)]

    for col in range(m):
        white_changes = 0
        black_changes = 0
        for row in range(n):
            if grid[row][col] == '.':
                black_changes += 1
            else:
                white_changes += 1
        cost[col][0] = white_changes
        cost[col][1] = black_changes

    # DP: dp[i][c] = minimum changes for first i columns where column i has color c
    # i ranges from 0 to m
    # c = 0 for white, c = 1 for black
    dp = [[float('inf')] * 2 for _ in range(m + 1)]
    dp[0][0] = 0  # 0 columns, 0 changes
    dp[0][1] = 0

    for i in range(1, m + 1):
        # Try to extend from j where width is between x and y
        for j in range(max(0, i - y), i):
            # Column i has color c, column j has color c
            if dp[j][0] != float('inf'):
                # Check if width from j to i-1 is between x and y
                width = i - j
                if x <= width <= y:
                    dp[i][0] = min(dp[i][0], dp[j][0] + sum(cost[k][0] for k in range(j, i)))
            if dp[j][1] != float('inf'):
                # Check if width from j to i-1 is between x and y
                width = i - j
                if x <= width <= y:
                    dp[i][1] = min(dp[i][1], dp[j][1] + sum(cost[k][1] for k in range(j, i)))

    print(min(dp[m][0], dp[m][1]))

solve()
