u = []
for _ in range(n):
    u.append(list(map(int, input().split())))

# Precompute unfamiliar values for all possible segments
# unfamiliar[a][b] = sum of u[i][j] for i from a to b, j from i to b (1-indexed)
unfamiliar = [[0] * (n + 1) for _ in range(n + 1)]
for a in range(1, n + 1):
    for b in range(a, n + 1):
        if a == b:
            unfamiliar[a][b] = 0
        else:
            unfamiliar[a][b] = unfamiliar[a][b-1] + sum(u[i-1][j-1] for i in range(a, b+1) for j in range(i, b+1))

# DP table
INF = float('inf')
dp = [[INF] * (k + 1) for _ in range(n + 1)]
dp[0][0] = 0

for i in range(1, n + 1):
    for j in range(1, min(i, k) + 1):
        for l in range(1, i - j + 2):  # last gondola has l people
            if j - 1 <= i - l:
                dp[i][j] = min(dp[i][j], dp[i - l][j - 1] + unfamiliar[i - l + 1][i])

print(dp[n][k])
