    col_cost_white = []
    col_cost_black = []

    for col in range(m):
        w = 0
        b = 0
        for row in range(n):
            if grid[row][col] == '.':
                w += 1
            else:
                b += 1
        col_cost_white.append(w)
        col_cost_black.append(b)

    # DP: dp[i][c] = minimum cost to process first i columns, ending with color c (0=white, 1=black)
    INF = float('inf')
    dp = [[INF] * 2 for _ in range(m + 1)]
    dp[0][0] = 0
    dp[0][1] = 0

    for i in range(1, m + 1):
        for c in range(2):
            # Try all possible block sizes w (x to y)
            for w in range(x, y + 1):
                start = i - w
                if start >= 0:
