                    # We must start with color 1 - c at column start
                    cost = col_cost_white[i - 1] if c == 0 else col_cost_black[i - 1]
                    for prev_color in range(2):
                        if dp[start][prev_color] != INF:
                            dp[i][c] = min(dp[i][c], dp[start][prev_color] + cost)

    print(min(dp[m][0], dp[m][1]))

