def max_overlap(a, b):
    """Find the maximum overlap where the suffix of a matches the prefix of b"""
    max_overlap = 0
    for i in range(min(len(a), len(b)), -1, -1):
        if a.endswith(b[:i]):
            max_overlap = i
            break
    return max_overlap

def shortest_superstring(s1, s2, s3):
    """Find the shortest string containing all three as substrings"""
    # First, check if one string already contains another
    if s2 in s1:
        if s3 in s1:
            return len(s1)
    if s1 in s2:
        if s3 in s2:
            return len(s2)
    if s1 in s3:
        if s2 in s3:
            return len(s3)

    from itertools import permutations

    min_length = float('inf')

    # Try all permutations of the 3 strings
    for perm in permutations([s1, s2, s3]):
        # Concatenate in this order and try to remove overlaps
        str1 = perm[0]
        str2 = perm[1]
        str3 = perm[2]

        # Overlap between first and second
        overlap1 = max_overlap(str1, str2)
        combined = str1 + str2[overlap1:]

        # Overlap between combined and third
        overlap2 = max_overlap(combined, str3)
        final = combined + str3[overlap2:]

        if len(final) < min_length:
            min_length = len(final)

    return min_length

# Read input
