def find_cycles(p):
    n = len(p)
    visited = [False] * (n + 1)
    cycles = []

    for i in range(1, n + 1):
        if not visited[i]:
            cycle = []
            j = i
            while not visited[j]:
                visited[j] = True
                cycle.append(j)
                j = p[j - 1]  # p is 0-indexed in list, but vertices are 1-indexed
            cycles.append(cycle)
    return cycles

def solve():
    n = int(input())
    p = list(map(int, input().split()))

    # Find cycles in the permutation
    cycles = find_cycles(p)

    # For each cycle, connect vertices to form a tree
    edges = []

    for cycle in cycles:
        # Connect each vertex to the vertex that maps to the first vertex in the cycle
        first = cycle[0]
        for v in cycle:
            if p[v - 1] == first:
                edges.append((v, first))
                break

    if len(edges) != n - 1:
        print("NO")
    else:
        print("YES")
        for u, v in edges:
            print(u, v)

