n, w, h = map(int, input().split())
envelopes = []
for i in range(n):
    wi, hi = map(int, input().split())
    if wi > w and hi > h:
        envelopes.append((wi, hi, i + 1))  # Store 1-indexed envelope number

if not envelopes:
    print(0)
else:
    # Sort by width, then by height (decreasing) to handle same widths
    envelopes.sort(key=lambda x: (x[0], -x[1]))

    # DP: lis[i] = (length of longest chain ending at i, previous index)
    lis = [(1, -1) for _ in range(len(envelopes))]

    for i in range(len(envelopes)):
        for j in range(i):
            # Check if envelope j can precede envelope i
            if envelopes[j][0] < envelopes[i][0] and envelopes[j][1] < envelopes[i][1]:
                if lis[j][0] + 1 > lis[i][0]:
                    lis[i] = (lis[j][0] + 1, j)

    # Find the envelope with maximum chain length
    max_len = max(lis, key=lambda x: x[0])[0]

    # Find any envelope that can be the start of a maximum chain
    for i, (length, _) in enumerate(lis):
        if length == max_len:
            # Backtrack to find the chain
            chain = []
            idx = i
            while idx != -1:
                chain.append(envelopes[idx][2])  # Append 1-indexed number
                idx = lis[idx][1]

            # Output the result
            print(max_len)
            print(' '.join(map(str, chain[::-1])))  # Reverse to get correct order
            break
