        a, b = b, a % b
    return a

n, m, dx, dy = map(int, input().split())
apple_trees = []
for _ in range(m):
    x, y = map(int, input().split())
    apple_trees.append((x, y))

# For each cell, find the cycle it belongs to
visited_cells = {}  # key: (x, y), value: (start_x, start_y)

# For each cell, find its cycle
for x in range(n):
    for y in range(n):
        if (x, y) not in visited_cells:
            # Find the cycle starting at (x, y)
            path = []
            cx, cy = x, y
            while (cx, cy) not in visited_cells:
                visited_cells[(cx, cy)] = (x, y)
                path.append((cx, cy))
                cx = (cx + dx) % n
                cy = (cy + dy) % n

            # Now we have all cells in this cycle
            # Mark them all with the same start point
            for cell in path:
                visited_cells[cell] = (x, y)

# Now find which start point has the most apple trees
start_counts = {}
for cell, start in visited_cells.items():
    if start not in start_counts:
        start_counts[start] = 0
    start_counts[start] += 1

# Find the start with maximum count
best_start = max(start_counts, key=start_counts.get)
print(best_start[0], best_start[1])
