import sys

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def expected_tosses(n):
    if n == 1:
        return 1  # Special case: only one knight, 0 tosses needed

    # Find the smallest k such that 2^k >= n
    k = 0
    while (1 << k) < n:
        k += 1

    # Expected tosses = k * 2^k / n
    # Output as irreducible fraction
    numerator = k * (1 << k)
    denominator = n

    # Simplify the fraction
    g = gcd(numerator, denominator)
    return f"{numerator // g}/{denominator // g}

n = int(sys.stdin.readline())
print(expected_tosses(n))
"}

