    # Try the standard algorithm
    result = [0] * n
    result[0] = a[-1]  # Place the largest at position 0
    result[1] = a[1]   # Place the second smallest at position 1

    for i in range(2, n):
        if i % 2 == 0:
            # Even index (0-indexed), place the next largest
            result[i] = a[n - 1 - (i//2)]
        else:
            # Odd index, place the next smallest
            result[i] = a[i//2 + 1]

    valid = True
    for i in range(n):
        left = result[(i - 1) % n]
        right = result[(i + 1) % n]
        if result[i] >= left + right:
            valid = False
            break

    if valid:
        print("YES")
        print(' '.join(map(str, result)))
    else:
        print("NO")
