def main():
    MOD = 10**9 + 7

    # Read input
    N, M, R = map(int, input().split())
    snakes = []
    for _ in range(N):
        X, Y, B = map(int, input().split())
        snakes.append((X, Y, B))

    # Precompute P(n, m) for all n and m up to N
    max_n = N
    fact = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        fact[i] = fact[i-1] * i % MOD

    def perm(n, m):
        """Permutation P(n, m) = n * (n-1) * ... * (n-m+1)"""
        if m == 0:
            return 1
        if n < m:
            return 0
        return fact[n] * pow(fact[n-m], MOD-2, MOD) % MOD

    # For each snake i, calculate c_i and d_ij
    c = [0] * N
    d = [[0] * N for _ in range(N)]

    for i in range(N):
        X_i, Y_i, B_i = snakes[i]

        # Find all snakes in kill zone of i
        kill_zone = set()
        for j in range(N):
            X_j, Y_j, B_j = snakes[j]
            if max(abs(X_i - X_j), abs(Y_i - Y_j)) <= R:
                kill_zone.add(j)
        S_i = len(kill_zone)

        c[i] = (perm(N, M) - perm(N - S_i, M)) % MOD

        # For d_ij with j > i
        for j in range(i+1, N):
            X_j, Y_j, B_j = snakes[j]

            # Find all snakes in kill zone of j
            for k in range(N):
                X_k, Y_k, B_k = snakes[k]
                if max(abs(X_j - X_k), abs(Y_j - Y_k)) <= R:
                    if k not in kill_zone:
                        kill_zone.add(k)
            S = len(kill_zone)

            # Inclusion-exclusion for d_ij
            d_ij = (perm(N, M) - perm(N - S_i, M) - perm(N - S_j, M) + perm(N - S, M)) % MOD
            d[i][j] = d_ij
            d[j][i] = d_ij

    # Calculate total score
    total = 0
    for i in range(N):
        total = (total + c[i] * snakes[i][2] * snakes[i][2]) % MOD

    for i in range(N):
        for j in range(i+1, N):
            total = (total + 2 * d[i][j] * snakes[i][2] * snakes[j][2]) % MOD

    print(total % MOD)

