def count_subarrays_with_at_least_k_equal(n, k, a):
    """
    Count subarrays with at least k equal numbers.
    """
    result = 0

    for i in range(n):
        freq = {}
        # Find the smallest j such that [i, j] contains at least k equal numbers
        for j in range(i, n):
            num = a[j]
            freq[num] = freq.get(num, 0) + 1

            # Check if any number has count >= k
            has_enough = False
            for val in freq:
                if freq[val] >= k:
                    has_enough = True
                    break

            if has_enough:
                # All subarrays [i, j], [i, j+1], ..., [i, n-1] are valid
                result += (n - j)
