import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    l = int(data[1])
    k = int(data[2])

    p = list(map(int, data[3:3+n]))
    a = list(map(int, data[3+n:6+n]))

    p = [x / 100.0 for x in p]

    max_cap = k + n * 200
    max_prize = n

    # dp[i][w][cap][prize] = probability
    dp = [[[[ -1.0 for _ in range(max_prize + 1)] for _ in range(max_cap + 1)] for _ in range(n + 1)] for _ in range(n + 1)]
    dp[0][0][0][0] = 1.0

    for i in range(n):
        for w in range(n + 1):
            for cap in range(max_cap + 1):
                for prize in range(max_prize + 1):
                    if dp[i][w][cap][prize] < 0:
                        continue

                    # Lose this tour
                    dp[i+1][w][cap][prize] = max(dp[i+1][w][cap][prize], dp[i][w][cap][prize])

                    # Win this tour
                    new_w = w + 1
                    if a[i] == -1:
                        new_cap = cap
                        new_prize = prize + 1
                    else:
                        new_cap = cap + a[i]
                        new_prize = prize

                    # Check if we have enough capacity
                    if new_cap >= new_prize:
                        dp[i+1][new_w][new_cap][new_prize] = max(dp[i+1][new_w][new_cap][new_prize], dp[i][w][cap][prize])


    answer = 0.0
    for w in range(l, n + 1):
        for cap in range(max_cap + 1):
            for prize in range(max_prize + 1):
                if cap >= prize:
                    answer += dp[n][w][cap][prize]

    print(f"{answer:.12f}")

if __name__ == "__main__":
    solve()
