def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        pieces = []
        for _ in range(n - 2):
            a, b, c = map(int, input().split())
            pieces.append(tuple(sorted([a, b, c])))

        # Build the order
        # Pick an arbitrary starting vertex
        start = pieces[0][0]
        order = [start]

        # Find neighbors of the starting vertex
        neighbors = set()
        for piece in pieces:
            if start in piece:
                neighbors.update(piece)
        neighbors.remove(start)

        # Build the order by picking neighbors
        prev = start
        for _ in range(n - 1):
            for piece in pieces:
                if prev in piece:
                    # Find the other vertex in this piece
                    for v in piece:
                        if v != prev:
                            if v in neighbors and len([p for p in pieces if prev in p and v in p]) == 1:
                                # This is the next neighbor
                                order.append(v)
                                neighbors.remove(v)
                                prev = v
                                break
                    else:
                        # This piece contains prev but no other neighbor
                        continue
                    break

        # Find the cutting order
        cut_order = []
        visited = set()
        for piece in pieces:
            # Find two vertices that are consecutive in the order
            for i in range(n - 1):
                if order[i] in piece and order[i + 1] in piece:
                    cut_order.append(piece)
                    visited.add(piece)
                    break

        print(' '.join(map(str, order)))
        print(' '.join(map(str, [i + 1 for i, piece in enumerate(cut_order)])))

solve()
