MOD = 10**9 + 7

def solve():
    N = int(input())
    tree = [[] for _ in range(N + 1)]
    for _ in range(N - 1):
        a, b = map(int, input().split())
        tree[a].append(b)
        tree[b].append(a)

    # Precompute powers of 2
    power2 = [1] * (N + 1)
    for i in range(1, N + 1):
        power2[i] = (power2[i-1] * 2) % MOD

    answer = 0

    # For each node as starting point
    for start in range(1, N + 1):
        # DFS to find all paths from start to leaves
        # And count 2^(L-1) for each path length L
        stack = [(start, -1, 1)]  # (node, parent, path_length)
        while stack:
            node, parent, length = stack.pop()
            if len(tree[node]) == 1 and node != start:
                # Found a leaf (except for start node which has only one connection)
                answer = (answer + power2[length - 1]) % MOD
            else:
                for neighbor in tree[node]:
                    if neighbor != parent:
                        stack.append((neighbor, node, length + 1))

    print(answer % MOD)

solve()
