import sys

def number_of_ones(d):
    """Return the number of 1s in the binary representation of d."""
    return bin(d).count('1')

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Precompute number of moves for each distance up to n-1
    moves = [0] * (n)  # index 0 unused
    for d in range(1, n):
        moves[d] = number_of_ones(d)

    # Compute answer for each k from 1 to n-1
    ans = []
    for k in range(1, n):
        total = 0
        for i in range(1, k + 1):
            d = k + 1 - i
            total += a[i - 1] * moves[d]
        ans.append(total)

    sys.stdout.write('\n'.join(map(str, ans)))

if __name__ == "__main__":
    solve()
