# Build original graph
original_graph = [[] for _ in range(n + 1)]

for _ in range(m):
    v, u, w = map(int, input().split())
    original_graph[v].append((u, w))
    original_graph[u].append((v, w))

# Build transformed graph where we can go through two roads at a time
transformed_graph = [[] for _ in range(n + 1)]

# For every edge (a-b) and (b-c), add edge (a-c) with weight (w_ab + w_bc)^2
for a in range(1, n + 1):
    for b, w_ab in original_graph[a]:
        for c, w_bc in original_graph[b]:
            if a != c:
                transformed_graph[a].append((c, (w_ab + w_bc) ** 2))

# Use Dijkstra's algorithm on transformed graph
import heapq

pq = [(0, 1)]
distance = {i: float('inf') for i in range(1, n + 1)}
distance[1] = 0
visited = set()

while pq:
    cost, city = heapq.heappop(pq)
    if city in visited:
        continue
    visited.add(city)

    for neighbor, weight in transformed_graph[city]:
        if cost + weight < distance[neighbor]:
            distance[neighbor] = cost + weight
            heapq.heappush(pq, (distance[neighbor], neighbor))

print(' '.join(map(str, [distance[i] if distance[i] != float('inf') else -1 for i in range(1, n + 1)])))
