from math import log2, ceil
from fractions import Fraction

def solve(n):
    if n == 1:
        return Fraction(1, 1)

    # Check if n is a power of 2
    if (n & (n - 1)) == 0:
        # n is a power of 2
        return Fraction(int(log2(n)), 1)

    # Find the number of bits needed
    k = ceil(log2(n))

    # Expected number of tosses
