def find_orbits(n, p):
    """Find all orbits under permutation p"""
    orbits = []
    visited = set()

    for i in range(1, n + 1):
        if i not in visited:
            current = i
            orbit = []

            while current not in visited:
                visited.add(current)
                orbit.append(current)
                current = p[current - 1]  # p is 0-indexed in the array

            orbits.append(orbit)

    return orbits


def is_power_of_two(x):
    """Check if x is a power of two"""
    return (x & (x - 1)) == 0


