    vol, cap, idx = kayaks[i]

    # Update from right to left
    for j in range(len(catamarans), -1, -1):
        # Try taking this kayak
        if i * 1 + j * 2 + vol <= v:
            new_cap = dp[i][j][0] + cap
            new_indices = dp[i][j][1].copy()
            new_indices.append(idx)

            if new_cap > dp[i + 1][j][0]:
                dp[i + 1][j] = (new_cap, new_indices)

# Fill DP table for catamarans
for j in range(len(catamarans)):
    vol, cap, idx = catamarans[j]

    # Update from right to left
    for i in range(len(kayaks), -1, -1):
        # Try taking this catamaran
