import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    # First value is n
    n = int(data[0])

    # The rest are Alice's colors
    colors = [int(data[i]) for i in range(1, n * n + 1)]

    # Initialize grid
    grid = [[None for _ in range(n)] for _ in range(n)]

    # Get color for each cell based on position
    def get_color(i, j):
