        # Create list of (next_value, index) pairs
        next_pairs = []
        for i in range(n):
            next_val = next_list[i]
            if next_val != -1:
                next_pairs.append((next_val, i))

        # Sort by next_value (largest first)
        next_pairs.sort(reverse=True)

        # Assign values
        assigned = [False] * n
        values = [0] * n
        remaining = list(range(1, n + 1))

        for next_val, idx in next_pairs:
            if next_val == n + 1:
                # No larger element, assign smallest remaining
                values[idx] = remaining.pop(0)
            else:
                # Assign largest remaining
                values[idx] = remaining.pop()

            # Mark as assigned
            assigned[idx] = True

        # Assign remaining values to positions with no next info
        for i in range(n):
            if not assigned[i] and next_list[i] == -1:
                values[i] = remaining.pop(0)

        # Check if there are remaining values (shouldn't happen)
        if remaining:
            results.append("-1")
        else:
            results.append(" ".join(map(str, values)))

    sys.stdout.write("\n".join(results))

