    """Check if the sequence of plays and clears is valid."""
    # Check if plays is non-decreasing
    for i in range(1, len(p)):
        if p[i] < p[i-1]:
            return False

    # Check if clears is non-decreasing
    for i in range(1, len(c)):
        if c[i] < c[i-1]:
            return False

    # Check if clears never exceeds plays
    for i in range(len(p)):
        if c[i] > p[i]:
            return False

    # Check if the differences between consecutive observations are valid
    for i in range(1, len(p)):
        plays_diff = p[i] - p[i-1]
        clears_diff = c[i] - c[i-1]

        # At least as many plays as clears between observations
        if plays_diff < clears_diff:
            return False

        # The number of clears cannot exceed the number of plays at any point
        # We need to check if the clears could have been distributed among the plays
        # The clears between observations must be ≤ plays_diff
